      if (newline !== -1) {
        let end = newline;

        if (end > 0 && buffer.charCodeAt(end - 1) === 13) {
          end -= 1;
        }

        const text = buffer.slice(0, end);
        buffer = buffer.slice(newline + 1);

        const event = parseLine(text);

        if (event !== NO_EVENT) {
          return event;
        }

        continue;
      }

      if (!sourceDone || buffer.length === 0) {
        return NO_EVENT;
      }

      const text = buffer;
      buffer = "";

      const event = parseLine(text);

      if (event !== NO_EVENT) {
        return event;
      }
    }
  }

  async function next() {
    if (status === CLOSED || status === EOF || status === FAILED) {
      return doneResult();
    }

    acquireIterator();

    for (;;) {
      const event = takeEvent();

      if (event !== NO_EVENT) {
        return { done: false, value: event };
      }

      if (sourceDone) {
        status = EOF;
        return doneResult();
      }

      let result;

      try {
        result = await iterator.next();
      } catch (error) {
        await failRead(error);
        throw error;
      }

      if (status === CLOSED) {
        return doneResult();
      }

      let isDone;

      try {
        if (
          result === null ||
          (typeof result !== "object" && typeof result !== "function")
        ) {
          throw new TypeError("async iterator result is invalid");
        }

        isDone = Boolean(result.done);
      } catch (error) {
        await failRead(error);
        throw error;
      }

      if (isDone) {
        sourceDone = true;

        let tail;

        try {
          tail = decoder.decode();
        } catch (error) {
          await failRead(error);
          throw error;
        }

        buffer += tail;
        continue;
      }

      let decoded;

      try {
        decoded = decoder.decode(result.value, { stream: true });
      } catch (error) {
        await failRead(error);
        throw error;
      }

      buffer += decoded;
    }
  }

  function close() {
    if (closePromise !== null) {
      return closePromise;
    }

    closePromise = (async function () {
      if (status === NEW) {
        status = CLOSED;
        return;
      }

      if (status === OPEN) {
        status = CLOSED;

        if (!sourceDone) {
          await startReturn();
        }

        return;
      }

      if (status === FAILED && returnPromise !== null) {
        await returnPromise;
      }
    })();

    return closePromise;
  }

  return { next, close };
}
